item.aggregated_output:
                completedSteps++;
//                delay(60);   // uncomment this to run more slowly
            }
            if(!currentState.isViable()) {
                updateBestSimulationResult(completedSteps);
                playingSimulation = false;
            }
        }

        remainingSteps = Math.max(0, numSteps - completedSteps);
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each organism.
     */
    public void simulateOneStep()
    {
        if(!playingSimulation) {
            return;
        }

        step++;
        environment.advance(step);

        List<Actor> newActors = new ArrayList<>();
        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
            Actor actor = it.next();
            processActor(actor, newActors);
            maybeGrowPlant(actor);

            if(!actor.isAlive()) {
                it.remove();
            }
        }

        actors.addAll(newActors);
        actors.addAll(organismFactory.createGrassPatches(field, environment));
        publishState();
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        playingSimulation = false;
        remainingSteps = 0;
        step = 0;
        environment.reset();

        actors.clear();
        actors.addAll(organismFactory.populate(field));

        publishState();
    }

    /**
     * Pause for a given time.
     * @param millisec  The time to pause for, in milliseconds
     */
    private void delay(int millisec)
    {
        try {
            Thread.sleep(millisec);
        }
        catch (InterruptedException ie) {
            // wake up
        }
    }

    private void processActor(Actor actor, List<Actor> newActors)
    {
        Random rand = randomProvider.getRandom();
        if(actor instanceof Animal animal) {
            if(!animal.isAwake(environment)) {
                return;
            }
            if(animal.isDiseased() && animal.getDisease().getPropagationRate() <= rand.nextDouble()) {
                animal.setDead();
            }
        }

        if(actor.isAlive()) {
            actor.act(newActors, environment);
        }
    }

    private void maybeGrowPlant(Actor actor)
    {
        if(actor instanceof Plant plant && step % plant.getStepsPerStage() == 0) {
            plant.incrementGrowth();
        }
    }

    private void publishState()
    {
        currentState = SimulationState.capture(step, environment, field);
        for(SimulationObserver observer : observers) {
            observer.onStateChanged(currentState);
        }
    }

    private void updateBestSimulationResult(int completedSteps)
    {
        if(completedSteps > SimulationInfo.HIGHEST_STEPS) {
            SimulationInfo.HIGHEST_STEPS = completedSteps;
            SimulationInfo.HIGHEST_STEP_PROBS = config.getCreationProbabilities();
        }
    }
}

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Random;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 2022.03.02
 */
public abstract class Animal extends Organism implements Actor
{
    private static final double RANDOM_CONTRACTION_RATE = 0.002;

    protected int age;
    protected boolean isNocturnal;
    protected int foodLevel;
    protected Gender sex;

    // An animal is either male or female 
    protected enum Gender {
        MALE,
        FEMALE
    }


    // Declaring abstract methods to obtain fields used by subclasses
    // These methods have been declared in order to use common methods in the Animal class, reducing repeatability
    protected abstract int getBreedingAge();
    protected abstract int getMaxLitterSize();
    protected abstract double getBreedingProbability();
    protected abstract int getMaxAge();
    protected abstract int getMaxFoodLevel();
    protected abstract Set<Class<? extends Organism>> getDiet();


    /**
     * Create a new animal at location in field.
     *
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param randomAge The animal's random starting age.
     * @param sex The animal's gender. 
     */
    public Animal(RandomProvider randomProvider, Field field, Location location, boolean randomAge, Gender sex)
    {
        super(randomProvider, field, location);
        this.sex = sex;
        Random rand = getRandomProvider().getRandom();
        if(randomAge) {
            this.age = rand.nextInt(getMaxAge());
            foodLevel = rand.nextInt(getMaxFoodLevel());
        }
        else {
            this.age = 0;
            foodLevel = getMaxFoodLevel();
        }
        randomlyContractDisease();
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * @param newAnimals A list to receive newly born animals.
     * @param environment The environment that the animal resides in.
     */
    public void act(List<Actor> newAnimals, Environment environment)
    {
        Random rand = getRandomProvider().getRandom();
        randomlyContractDisease();
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            giveBirth(newAnimals, environment);
            // Move towards a source of food if found.
            Location newLocation = findFood(environment);
            if(newLocation == null) {
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }

            // list of adjacent locations that contain an instance of Grass
            List<Location> adjacentGrassSpots = getField().adjacentLocationsWithSpecies(getLocation(), Grass.class);

            if(newLocation != null) {
                // See if it was possible to move.
                setLocation(newLocation);
            }
            else if (adjacentGrassSpots.size() > 0) {
                // if there is grass adjacent to the animal, clear the current location
                // and move to a random location that contained grass
                getField().clear(getLocation());
                setLocation(adjacentGrassSpots.get(rand.nextInt(adjacentGrassSpots.size())));
            }
            else {
                // Overcrowding
                setDead();
            }

            if(isDiseased() && getDisease().getLethalityRate() <= rand.nextDouble()){
                // every step, check if the Animal is diseased
                // if it is Diseased, and a random double is less than the lethality rate, the Animal dies
                setDead();
            }

        }
    }

    /**
     * Look for food adjacent to the current location.
     * Only the first food is eaten.
     * @return Where food was found, or null if it wasn't.
     */
    protected Location findFood(Environment environment)
    {
        return findFood();
    }

    /**
     * Look for food adjacent to the current location.
     * Only the first food is eaten.
     * @return Where food was found, or null if it wasn't.
     */
    protected Location findFood()
    {
        Random rand = getRandomProvider().getRandom();
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        for(Location loc : adjacent){
            if(field.getObjectAt(loc) != null && !(field.getObjectAt(loc) instanceof Hunter)){
                Organism organism = (Organism) field.getObjectAt(loc);
                if (organism.isDiseased() && organism.getDisease().getDiseaseType() != DiseaseType.CONTACT && organism.getDisease().getPropagationRate() <= rand.nextDouble()){
                    // contracts the first contact disease it encounters amongst the adjacent animals
                    this.setDisease(organism.getDisease());
                    break;
                }
            }
        }
        Iterator<Location> it = adjacent.iterator();
        // only eats if it's not full (food level less than max)
        while(it.hasNext() && foodLevel <= getMaxFoodLevel()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal != null && getDiet().contains(animal.getClass()))
            {
                Organism food = (Organism) animal;
                if (food.isDiseased() &&  food.getDisease().getDiseaseType() == DiseaseType.FOODBORNE && food.getDisease().getPropagationRate() <= rand.nextDouble()) 
                {
                    // contracts disease from food if it has a disease and that disease is foodborne
                    setDisease(food.getDisease());
                }
                if(food.isAlive()) 
                {
                    food.setDead();
                    int newFoodLevel = foodLevel + food.getFoodValue();

                    // caps the food level at the maximum
                    foodLevel = Math.min(newFoodLevel, getMaxFoodLevel());

                    return where;
                }
                return where;
            }
        }
        return null;
    }

    /**
     * Returns true if an animal contracts a disease at birth.
     * Returns false if otherwise. 
     */
    protected void randomlyContractDisease()
    {
        Random rand = getRandomProvider().getRandom();
        if(rand.nextDouble() <= RANDOM_CONTRACTION_RATE) {
            setDisease(new Disease(getRandomProvider()));
        }
    }

    /**
     * Check whether this animal is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newAnimals A list to return newly born animals.
     * @param environment The environment that the animal resides in. 
     */
    protected void giveBirth(List<Actor> newAnimals, Environment environment)
    {
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && !free.isEmpty(); b++) {
            Location loc = free.remove(0);
            Gender sex = getRandomProvider().getRandom().nextBoolean() ? Gender.MALE : Gender.FEMALE;
            newAnimals.add(createYoung(field, loc, sex));
        }
    }

    protected Animal createYoung(Field field, Location location, Gender sex)
    {
        return field.getOrganismFactory().createOffspring(getClass().asSubclass(Animal.class), field, location, sex);
    }

    /**
     * Returns true if the animal is awake or not.
     */
    public boolean isAwake(Environment environment)
    {
        if(isNocturnal){
            return !environment.getTime().isDay();
        }
        return environment.getTime().isDay();
    }

    /**
     * Generates a number representing the number of births,
     * if it can breed.
     * @return The number of births (may be zero)
     */
    protected int breed()
    {
        Random rand = getRandomProvider().getRandom();
        int births = 0;
        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
            births = rand.nextInt(getMaxLitterSize()) + 1;
            Animal mate = (Animal) getPotentialMates().get(rand.nextInt(getPotentialMates().size()));
            if(mate.isDiseased() && mate.getDisease().getDiseaseType() == DiseaseType.SEXUAL){
                this.setDisease(mate.getDisease());
            }
        }
        return births;
    }

    /**
     * Returns true if the animal is able to breed.
     * Returns false if otherwise. 
     */
    protected boolean canBreed()
    {
        return age >= getBreedingAge() && !getPotentialMates().isEmpty();
    }

    /**
     * Returns a list of potential mates. Mates have to be
     * of a opposite gender. 
     * @return List<Organism> A list of potential mates.
     */
    protected List<Organism> getPotentialMates()
    {
        List<Organism> potentialMates = new ArrayList<>();
        if(getField() != null){
            potentialMates = getField().adjacentLocations(getLocation()).stream()
                    .map(s -> getField().getObjectAt(s))
                    .filter(s -> s != null)
                    .filter(s -> s.getClass().equals(this.getClass()))
                    .filter(s -> this.sex != ((Animal) s).sex)
                    .map(s -> (Organism) s)
                    .collect(Collectors.toList());
            // stream counts the number of Animals of the same species, as well as opposite gender
        }
        return potentialMates;
    }


    /**
     * Increase the age. This could result in the animal's death.
     */
    protected void incrementAge()
    {
        this.age++;
        if(this.age > getMaxAge()) {
            setDead();
        }
    }

    /**
     * Make this animal more hungry. This could result in the animal's death.
     */
    protected void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

}

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Immutable snapshot of the current simulation state.
 */
public class SimulationState
{
    private final int step;
    private final WeatherType weather;
    private final String time;
    private final Field field;
    private final Map<Class<?>, Integer> populationCounts;
    private final int diseasedPopulation;
    private final boolean viable;

    private SimulationState(int step,
            WeatherType weather,
            String time,
            Field field,
            Map<Class<?>, Integer> populationCounts,
            int diseasedPopulation,
            boolean viable)
    {
        this.step = step;
        this.weather = weather;
        this.time = time;
        this.field = field;
        this.populationCounts = Collections.unmodifiableMap(populationCounts);
        this.diseasedPopulation = diseasedPopulation;
        this.viable = viable;
    }

    public static SimulationState capture(int step, Environment environment, Field field)
    {
        Map<Class<?>, Integer> populationCounts = new LinkedHashMap<>();
        for(Class<?> actorClass : SimulationInfo.ALL_ACTORS) {
            populationCounts.put(actorClass, 0);
        }

        int diseasedPopulation = 0;
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object actor = field.getObjectAt(row, col);
                if(actor != null) {
                    populationCounts.merge(actor.getClass(), 1, Integer::sum);
                    if(actor instanceof Organism organism && organism.isDiseased()) {
                        diseasedPopulation++;
                    }
                }
            }
        }

        int livingSpecies = 0;
        for(int count : populationCounts.values()) {
            if(count > 0) {
                livingSpecies++;
            }
        }

        return new SimulationState(
                step,
                environment.getWeather().getCurrentWeather(),
                environment.getTime().getCurrentTimeString(),
                field,
                populationCounts,
                diseasedPopulation,
                livingSpecies > 2
        );
    }

    public int getStep()
    {
        return step;
    }

    public WeatherType getWeather()
    {
        return weather;
    }

    public String getTime()
    {
        return time;
    }

    public Field getField()
    {
        return field;
    }

    public int getPopulationCount(Class<?> actorClass)
    {
        return populationCounts.getOrDefault(actorClass, 0);
    }

    public Map<Class<?>, Integer> getPopulationCounts()
    {
        return populationCounts;
    }

    public int getDiseasedPopulation()
    {
        return diseasedPopulation;
    }

    public boolean isViable()
    {
        return viable;
    }
}

/**
 * This class represents shared characteristics of organisms
 * in the simulation. 
 *
 * @version 2022.03.2
 */
public abstract class Organism {


    // Whether the organism is alive or not.
    private boolean alive;
    private final RandomProvider randomProvider;
    // The organism's field.
    private Field field;
    // The organism's position in the field.
    private Location location;

    // Whether the organism has a disease 
    private Disease disease = null;
    private boolean hasDisease = false;


    protected abstract int getFoodValue();

    /**
     * Creates a new organism. 
     */
    public Organism(RandomProvider randomProvider, Field field, Location location)
    {
        alive = true;
        this.randomProvider = randomProvider;
        this.field = field;
        setLocation(location);
    }

    /**
     * Place the organism at the new location in the given field.
     * @param newLocation The organism's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }


    /**
     * Return the organism's location.
     * @return The organism's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Return the organism's field.
     * @return The organism's field.
     */
    protected Field getField()
    {
        return field;
    }

    protected RandomProvider getRandomProvider()
    {
        return randomProvider;
    }

    /**
     * Check whether the organism is alive or not.
     * @return true if the organism is still alive.
     */
    public boolean isAlive()
    {
        return alive;
    }

    /**
     * Indicate that the organism is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Returns true if the organism is infected. 
     */
    public boolean isDiseased()
    {
        return hasDisease;
    }

    /**
     * Returns the organism's disease.
     * @return Disease The organism's disease.
     */
    public Disease getDisease()
    {
        return disease;
    }

    /**
     * Sets the organism to be infected.
     * @param disease The disease that the organism is gonna be infected by. 
     */
    protected void setDisease(Disease disease)
    {
        this.disease = disease;
        hasDisease = true;
    }
}

import java.util.Random;

/**
 * This class models disease in the simulation. 
 * It stores details about the disease such as 
 * lethality rate, propagation rate and the method of transmission.
 *
 * @version 2022.03.2
*/
public class Disease 
{
    // The propagation rate of the disease
    private static double PROPAGATION_RATE = 0.0;
    // the lethality rate of the disease
    private static double LETHALITY_RATE = 0.0;
    // the transmission route of the disease 
    private DiseaseType PROPAGATION_MODE;

    /**
     * Creates a new disease with random propagation and lethality rates.
     * double randomValue = rangeMin + (rangeMax - rangeMin) * r.nextDouble();
     * https://stackoverflow.com/questions/3680637/generate-a-random-double-in-a-range
     */
    public Disease(RandomProvider randomProvider) 
    {
        Random rand = randomProvider.getRandom();
        PROPAGATION_RATE = 0.6 * rand.nextDouble(); // max prop. rate is 60%
        LETHALITY_RATE = 0.4 * rand.nextDouble(); // max lethality rate is 40%
        PROPAGATION_MODE = DiseaseType.values()[rand.nextInt(DiseaseType.values().length)];
    }

    /**
     * Create a new disease with given propagation and lethality rates.
     * @param propRate The propagation rate of the disease.
     * @param lethalRate The lethality rate of the disease.
     * @param propMode The propagation mode of the disease. 
     */
    public Disease(double propRate, double lethalRate, DiseaseType propMode)
    {
        PROPAGATION_RATE = propRate;
        LETHALITY_RATE = lethalRate;
        PROPAGATION_MODE = propMode;
    }

    /**
     * Returns the propagation rate of the disease
     */
    public double getPropagationRate() 
    {
        return PROPAGATION_RATE;
    }

    /**
     * Returns the lethality rate of the disease
     */
    public double getLethalityRate() 
    {
        return LETHALITY_RATE;
    }

    /**
     * Returns the disease's mode of transmission
     */
    public DiseaseType getDiseaseType() 
    {
        return PROPAGATION_MODE;
    }
}

