  6	/**
  7	 * Centralizes disease creation, infection state, and transmission rules.
  8	 */
  9	public class DiseaseService
 10	{
 11	    private static final double RANDOM_CONTRACTION_RATE = 0.002;
 12	
 13	    private final RandomProvider randomProvider;
 14	    private final Map<Organism, Disease> infections;
 15	
 16	    public DiseaseService(RandomProvider randomProvider)
 17	    {
 18	        this.randomProvider = randomProvider;
 19	        this.infections = new IdentityHashMap<>();
 20	    }
 21	
 22	    public void initializeOrganism(Organism organism)
 23	    {
 24	        if(organism instanceof Animal) {
 25	            maybeInfectAtCreation(organism);
 26	        }
 27	    }
 28	
 29	    public void reset()
 30	    {
 31	        infections.clear();
 32	    }
 33	
 34	    public void unregister(Organism organism)
 35	    {
 36	        infections.remove(organism);
 37	    }
 38	
 39	    public boolean isDiseased(Organism organism)
 40	    {
 41	        return infections.containsKey(organism);
 42	    }
 43	
 44	    public Disease getDisease(Organism organism)
 45	    {
 46	        return infections.get(organism);
 47	    }
 48	
 49	    public void infect(Organism organism, Disease disease)
 50	    {
 51	        infections.put(organism, disease);
 52	    }
 53	
 54	    public boolean processPreAct(Animal animal)
 55	    {
 56	        if(!animal.isAlive()) {
 57	            return false;
 58	        }
 59	
 60	        if(shouldKillByPropagation(animal)) {
 61	            kill(animal);
 62	            return false;
 63	        }
 64	
 65	        maybeInfectAtCreation(animal);
 66	        return animal.isAlive();
 67	    }
 68	
 69	    public void processPostAct(Animal animal)
 70	    {
 71	        if(animal.isAlive() && shouldKillByLethality(animal)) {
 72	            kill(animal);
 73	        }
 74	    }
 75	
 76	    public void applyAdjacentExposure(Animal animal, List<Location> adjacentLocations, Field field)
 77	    {
 78	        for(Location location : adjacentLocations) {
 79	            Object nearby = field.getObjectAt(location);
 80	            if(nearby instanceof Organism organism
 81	                    && !(nearby instanceof Hunter)
 82	                    && isDiseased(organism)
 83	                    && getDisease(organism).getDiseaseType() != DiseaseType.CONTACT
 84	                    && succeeds(getDisease(organism).getPropagationRate())) {
 85	                infect(animal, getDisease(organism));
 86	                break;
 87	            }
 88	        }
 89	    }
 90	
 91	    public void applyFoodborneExposure(Animal animal, Organism food)
 92	    {
 93	        if(isDiseased(food)
 94	                && getDisease(food).getDiseaseType() == DiseaseType.FOODBORNE
 95	                && succeeds(getDisease(food).getPropagationRate())) {
 96	            infect(animal, getDisease(food));
 97	        }
 98	    }
 99	
100	    public void applySexualExposure(Animal animal, Animal mate)
101	    {
102	        if(isDiseased(mate) && getDisease(mate).getDiseaseType() == DiseaseType.SEXUAL) {
103	            infect(animal, getDisease(mate));
104	        }
105	    }
106	
107	    public Disease createRandomDisease()
108	    {
109	        return new Disease(randomProvider);
110	    }
111	
112	    private void maybeInfectAtCreation(Organism organism)
113	    {
114	        if(!isDiseased(organism) && succeeds(RANDOM_CONTRACTION_RATE)) {
115	            infect(organism, createRandomDisease());
116	        }
117	    }
118	
119	    private boolean shouldKillByPropagation(Animal animal)
120	    {
121	        return isDiseased(animal) && succeeds(getDisease(animal).getPropagationRate());
122	    }
123	
124	    private boolean shouldKillByLethality(Animal animal)
125	    {
126	        return isDiseased(animal) && succeeds(getDisease(animal).getLethalityRate());
127	    }
128	
129	    private boolean succeeds(double threshold)
130	    {
131	        Random rand = randomProvider.getRandom();
132	        return threshold <= rand.nextDouble();
133	    }
134	
135	    private void kill(Organism organism)
136	    {
137	        organism.setDead();
138	        unregister(organism);
139	    }
140	}

