 10	{
 11	    private final RandomProvider randomProvider;
 12	    private final OrganismFactory organismFactory;
 13	    private final DiseaseService diseaseService;
 14	
 15	    // The depth and width of the field.
 16	    private int depth, width;
 17	    // Storage for the animals.
 18	    private Object[][] field;
 19	
 20	    /**
 21	     * Represent a field of the given dimensions.
 22	     * @param depth The depth of the field.
 23	     * @param width The width of the field.
 24	     */
 25	    public Field(RandomProvider randomProvider,
 26	            OrganismFactory organismFactory,
 27	            DiseaseService diseaseService,
 28	            int depth,
 29	            int width)
 30	    {
 31	        this.randomProvider = randomProvider;
 32	        this.organismFactory = organismFactory;
 33	        this.diseaseService = diseaseService;
 34	        this.depth = depth;
 35	        this.width = width;
 36	        field = new Object[depth][width];
 37	    }
 38	    
 39	    /**
 40	     * Empty the field.
 41	     */
 42	    public void clear()
 43	    {
 44	        for(int row = 0; row < depth; row++) {
 45	            for(int col = 0; col < width; col++) {
 46	                field[row][col] = null;
 47	            }
 48	        }
 49	    }
 50	    
 51	    /**
 52	     * Clear the given location.
 53	     * @param location The location to clear.
 54	     */
 55	    public void clear(Location location)
 56	    {
 57	        field[location.getRow()][location.getCol()] = null;
 58	    }
 59	    
 60	    /**
 61	     * Place an animal at the given location.
 62	     * If there is already an animal at the location it will
 63	     * be lost.
 64	     * @param animal The animal to be placed.
 65	     * @param row Row coordinate of the location.
 66	     * @param col Column coordinate of the location.
 67	     */
 68	    public void place(Object animal, int row, int col)
 69	    {
 70	        place(animal, new Location(row, col));
 71	    }
 72	    
 73	    /**
 74	     * Place an animal at the given location.
 75	     * If there is already an animal at the location it will
 76	     * be lost.
 77	     * @param animal The animal to be placed.
 78	     * @param location Where to place the animal.
 79	     */
 80	    public void place(Object animal, Location location)
 81	    {
 82	        field[location.getRow()][location.getCol()] = animal;
 83	    }
 84	    
 85	    /**
 86	     * Return the animal at the given location, if any.
 87	     * @param location Where in the field.
 88	     * @return The animal at the given location, or null if there is none.
 89	     */
 90	    public Object getObjectAt(Location location)
 91	    {
 92	        return getObjectAt(location.getRow(), location.getCol());
 93	    }
 94	    
 95	    /**
 96	     * Return the animal at the given location, if any.
 97	     * @param row The desired row.
 98	     * @param col The desired column.
 99	     * @return The animal at the given location, or null if there is none.
100	     */
101	    public Object getObjectAt(int row, int col)
102	    {
103	        return field[row][col];
104	    }
105	
106	    /**
107	     * Returns the field of the simulation. 
108	     */
109	    public Object[][] getField()
110	    {
111	        return field;
112	    }
113	    
114	    /**
115	     * Generate a random location that is adjacent to the
116	     * given location, or is the same location.
117	     * The returned location will be within the valid bounds
118	     * of the field.
119	     * @param location The location from which to generate an adjacency.
120	     * @return A valid location within the grid area.
121	     */
122	    public Location randomAdjacentLocation(Location location)
123	    {
124	        List<Location> adjacent = adjacentLocations(location);
125	        return adjacent.get(0);
126	    }
127	
128	    /**
129	     * Returns a random set of patches from getFreePatches() based on a given rate
130	     * getFreePatches() returns a list of size n, only (n*rate) random locations are returned
131	     * @param rateOfGeneration The rate
132	     */
133	    public List<Location> getRandomFreePatches(double rateOfGeneration)
134	    {
135	        Random rand = randomProvider.getRandom();
136	        List<Location> patches = getFreePatches();
137	        List<Location> randPatches = new ArrayList<>();
138	        for(int i=0; i<rateOfGeneration* patches.size(); i++)
139	        {
140	            Location selectedPatch = patches.get(rand.nextInt(patches.size()));
141	            randPatches.add(selectedPatch);
142	            for(Location loc : adjacentLocations(selectedPatch)){
143	                // avoids duplicates in the patches
144	                patches.remove(loc);
145	            }
146	        }
147	        return randPatches;
148	    }
149	
150	    /**
151	     * Gets the free patches in the field and returns them.
152	     * A 'patch' is a 3x3 square of locations, the locations in the list are the centers of said squares
153	     * Patches do not overlap, so the adjacent locations of one patch don't have common locations with
154	     * the adjacent locations of any other square
155	     *
156	     * @return The list of free patches in the field.
157	     */
158	    public List<Location> getFreePatches()
159	    {
160	        List<Location> res = new ArrayList<>();
161	        for(int i=0; i<field.length; i++){
162	            for(int j=0; j<field[1].length; j++){
163	                if (field[i][j] == null){
164	                    List<Location> nearby = adjacentLocations(new Location(i, j));
165	                    boolean allNulls = true;
166	                    for(Location loc : nearby){
167	                        if(getObjectAt(loc) != null){
168	                            allNulls = false;
169	                        }
170	                    }
171	                    if(allNulls){
172	                        res.add(new Location(i, j));
173	                    }
174	                }
175	            }
176	        }
177	
178	        return res;
179	    }
180	
181	    /**
182	     * Get a shuffled list of the free adjacent locations.
183	     * @param location Get locations adjacent to this.
184	     * @return A list of free adjacent locations.
185	     */
186	    public List<Location> getFreeAdjacentLocations(Location location)
187	    {
188	        List<Location> free = new LinkedList<>();
189	        List<Location> adjacent = adjacentLocations(location);
190	        for(Location next : adjacent) {
191	            Object objectAtNext = getObjectAt(next);
192	            if(objectAtNext == null) {
193	                free.add(next);
194	            }
195	        }
196	        return free;
197	    }
198	
199	    /**
200	     * Try to find a free location that is adjacent to the
201	     * given location. If there is none, return null.
202	     * The returned location will be within the valid bounds
203	     * of the field.
204	     * @param location The location from which to generate an adjacency.
205	     * @return A valid location within the grid area.
206	     */
207	    public Location freeAdjacentLocation(Location location)
208	    {
209	        // The available free ones.
210	        List<Location> free = getFreeAdjacentLocations(location);
211	        if(free.size() > 0) {
212	            return free.get(0);
213	        }
214	        else {
215	            return null;
216	        }
217	    }
218	
219	    /**
220	     * Returns adjacent locations in the field containing a certain class
221	     * For example, adjacentSpecies(location, Grass.class) returns the adjacent locations with Grass
222	     * @param location The location of an organism.
223	     * @param speciesClass The type of species.
224	     * @return adjacentSpecies A list of adjacent locations with the specified species 
225	     */
226	    public List<Location> adjacentLocationsWithSpecies(Location location, Class<?> speciesClass) {
227	        List<Location> free = adjacentLocations(location);
228	        List<Location> res = new ArrayList<>();
229	        for (Location loc : free) {
230	            if (getObjectAt(loc) != null && getObjectAt(loc).getClass()==speciesClass) {
231	                res.add(loc);
232	            }
233	        }
234	        return res;
235	    }
236	
237	    /**
238	     * Return a shuffled list of locations adjacent to the given one.
239	     * The list will not include the location itself.
240	     * All locations will lie within the grid.
241	     * @param location The location from which to generate adjacencies.
242	     * @return A list of locations adjacent to that given.
243	     */
244	    public List<Location> adjacentLocations(Location location)
245	    {
246	        assert location != null : "Null location passed to adjacentLocations";
247	        // The list of locations to be returned.
248	        List<Location> locations = new LinkedList<>();
249	        if(location != null) {
250	            int row = location.getRow();
251	            int col = location.getCol();
252	            for(int roffset = -1; roffset <= 1; roffset++) {
253	                int nextRow = row + roffset;
254	                if(nextRow >= 0 && nextRow < depth) {
255	                    for(int coffset = -1; coffset <= 1; coffset++) {
256	                        int nextCol = col + coffset;
257	                        // Exclude invalid locations and the original location.
258	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
259	                            locations.add(new Location(nextRow, nextCol));
260	                        }
261	                    }
262	                }
263	            }
264	            
265	            // Shuffle the list. Several other methods rely on the list
266	            // being in a random order.
267	            Collections.shuffle(locations, randomProvider.getRandom());
268	        }
269	        return locations;
270	    }
271	
272	    /**
273	     * Return the depth of the field.
274	     * @return The depth of the field.
275	     */
276	    public int getDepth()
277	    {
278	        return depth;
279	    }
280	    
281	    /**
282	     * Return the width of the field.
283	     * @return The width of the field.
284	     */
285	    public int getWidth()
286	    {
287	        return width;
288	    }
289	
290	    public RandomProvider getRandomProvider()
291	    {
292	        return randomProvider;
293	    }
294	
295	    public OrganismFactory getOrganismFactory()
296	    {
297	        return organismFactory;
298	    }
299	
300	    public DiseaseService getDiseaseService()
301	    {
302	        return diseaseService;
303	    }
304	}

