 27	        this.weather = weather;
 28	        this.time = time;
 29	        this.field = field;
 30	        this.populationCounts = Collections.unmodifiableMap(populationCounts);
 31	        this.diseasedPopulation = diseasedPopulation;
 32	        this.viable = viable;
 33	    }
