 35	    public static SimulationState capture(int step, Environment environment, Field field)
 36	    {
 37	        DiseaseService diseaseService = field.getDiseaseService();
 38	        Map<Class<?>, Integer> populationCounts = new LinkedHashMap<>();
 39	        for(Class<?> actorClass : SimulationInfo.ALL_ACTORS) {
 40	            populationCounts.put(actorClass, 0);
 41	        }
 42	
 43	        int diseasedPopulation = 0;
 44	        for(int row = 0; row < field.getDepth(); row++) {
 45	            for(int col = 0; col < field.getWidth(); col++) {
 46	                Object actor = field.getObjectAt(row, col);
 47	                if(actor != null) {
 48	                    populationCounts.merge(actor.getClass(), 1, Integer::sum);
 49	                    if(actor instanceof Organism organism && diseaseService.isDiseased(organism)) {
 50	                        diseasedPopulation++;
 51	                    }
 52	                }
 53	            }
 54	        }
 55	
 56	        int livingSpecies = 0;
 57	        for(int count : populationCounts.values()) {
 58	            if(count > 0) {
 59	                livingSpecies++;
 60	            }
 61	        }
 62	
 63	        return new SimulationState(
 64	                step,
 65	                environment.getWeather().getCurrentWeather(),
 66	                environment.getTime().getCurrentTimeString(),
 67	                field,
 68	                populationCounts,
 69	                diseasedPopulation,
 70	                livingSpecies > 2
 71	        );
 72	    }
