115	    private Simulator(RandomProvider randomProvider, SimulationConfig config, int depth, int width)
116	    {
117	        if(width <= 0 || depth <= 0) {
118	            System.out.println("The dimensions must be greater than zero.");
119	            System.out.println("Using default values.");
