160	    /**
161	     * Run the simulation from its current state for a reasonably long period.
162	     */
163	    public void runLongSimulation()
164	    {
165	        remainingSteps += SimulationConfig.LONG_SIMULATION_STEPS;
166	        simulate(remainingSteps);
167	    }
