169	    /**
170	     * Start a long simulation on a background thread.
171	     */
172	    public void startLongSimulation()
173	    {
174	        if(playingSimulation) {
175	            System.out.println("Stop the simulation first");
176	            return;
177	        }
178	
179	        Thread runLongSimThread = new Thread(this::runLongSimulation, "SimulationRunThread");
180	        runLongSimThread.start();
181	    }
