183	    /**
184	     * Run a single simulation step if the simulator is currently idle.
185	     */
186	    public void stepOnce()
187	    {
188	        if(playingSimulation) {
189	            System.out.println("Stop the simulation first");
190	            return;
191	        }
192	
193	        playingSimulation = true;
194	        simulateOneStep();
195	        playingSimulation = false;
196	    }
197	
198	    /**
199	     * Stop the simulation loop.
200	     */
201	    public void stop()
202	    {
203	        playingSimulation = false;
204	    }
205	
206	    /**
207	     * Run the simulation from its current state for the given number of steps.
208	     * Stop before the given number of steps if it ceases to be viable.
209	     * @param numSteps The number of steps to run for.
210	     */
211	    public void simulate(int numSteps)
212	    {
213	        playingSimulation = true;
214	        remainingSteps = numSteps;
215	
216	        int completedSteps = 0;
217	        while(playingSimulation) {
218	            for(int currentStep = 0;
219	                    currentStep < numSteps && playingSimulation && currentState.isViable();
220	                    currentStep++) {
221	                simulateOneStep();
222	                completedSteps++;
223	//                delay(60);   // uncomment this to run more slowly
224	            }
225	            if(!currentState.isViable()) {
226	                updateBestSimulationResult(completedSteps);
227	                playingSimulation = false;
228	            }
229	        }
230	
231	        remainingSteps = Math.max(0, numSteps - completedSteps);
232	    }
233	
234	    /**
235	     * Run the simulation from its current state for a single step.
236	     * Iterate over the whole field updating the state of each organism.
237	     */
238	    public void simulateOneStep()
239	    {
240	        if(!playingSimulation) {
241	            return;
242	        }
243	
244	        step++;
245	        environment.advance(step);
246	
247	        List<Actor> newActors = new ArrayList<>();
248	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
249	            Actor actor = it.next();
250	            processActor(actor, newActors);
251	            maybeGrowPlant(actor);
252	
253	            if(!actor.isAlive()) {
254	                if(actor instanceof Organism organism) {
255	                    diseaseService.unregister(organism);
256	                }
257	                it.remove();
258	            }
259	        }
260	
261	        actors.addAll(newActors);
262	        actors.addAll(organismFactory.createGrassPatches(field, environment));
263	        publishState();
264	    }
265	
266	    /**
267	     * Reset the simulation to a starting position.
268	     */
269	    public void reset()
270	    {
271	        playingSimulation = false;
272	        remainingSteps = 0;
273	        step = 0;
274	        environment.reset();
275	        diseaseService.reset();
276	
277	        actors.clear();
278	        actors.addAll(organismFactory.populate(field));
279	
280	        publishState();
281	    }
282	
283	    /**
284	     * Pause for a given time.
285	     * @param millisec  The time to pause for, in milliseconds
286	     */
287	    private void delay(int millisec)
288	    {
289	        try {
290	            Thread.sleep(millisec);
291	        }
292	        catch (InterruptedException ie) {
293	            // wake up
294	        }
295	    }
296	
297	    private void processActor(Actor actor, List<Actor> newActors)
298	    {
299	        if(actor instanceof Animal animal) {
300	            if(!animal.isAwake(environment)) {
301	                return;
302	            }
303	            if(!diseaseService.processPreAct(animal)) {
304	                return;
305	            }
306	        }
307	
308	        if(actor.isAlive()) {
309	            actor.act(newActors, environment);
310	            if(actor instanceof Animal animal) {
311	                diseaseService.processPostAct(animal);
312	            }
313	        }
314	    }
315	
316	    private void maybeGrowPlant(Actor actor)
317	    {
318	        if(actor instanceof Plant plant && step % plant.getStepsPerStage() == 0) {
319	            plant.incrementGrowth();
320	        }
321	    }
322	
323	    private void publishState()
324	    {
325	        currentState = SimulationState.capture(step, environment, field);
326	        for(SimulationObserver observer : observers) {
327	            observer.onStateChanged(currentState);
328	        }
329	    }
330	
331	    private void updateBestSimulationResult(int completedSteps)
332	    {
333	        if(completedSteps > SimulationInfo.HIGHEST_STEPS) {
334	            SimulationInfo.HIGHEST_STEPS = completedSteps;
335	            SimulationInfo.HIGHEST_STEP_PROBS = config.getCreationProbabilities();
336	        }
337	    }
338	}

