  8	/**
  9	 * A class representing shared characteristics of animals.
 10	 *
 11	 * @version 2022.03.02
 12	 */
 13	public abstract class Animal extends Organism implements Actor
 14	{
 15	    protected int age;
 16	    protected boolean isNocturnal;
 17	    protected int foodLevel;
 18	    protected Gender sex;
 19	
 20	    // An animal is either male or female 
 21	    protected enum Gender {
 22	        MALE,
 23	        FEMALE
 24	    }
 25	
 26	
 27	    // Declaring abstract methods to obtain fields used by subclasses
 28	    // These methods have been declared in order to use common methods in the Animal class, reducing repeatability
 29	    protected abstract int getBreedingAge();
 30	    protected abstract int getMaxLitterSize();
 31	    protected abstract double getBreedingProbability();
 32	    protected abstract int getMaxAge();
 33	    protected abstract int getMaxFoodLevel();
 34	    protected abstract Set<Class<? extends Organism>> getDiet();
 35	
 36	
 37	    /**
 38	     * Create a new animal at location in field.
 39	     *
 40	     * @param field The field currently occupied.
 41	     * @param location The location within the field.
 42	     * @param randomAge The animal's random starting age.
 43	     * @param sex The animal's gender. 
 44	     */
 45	    public Animal(RandomProvider randomProvider, Field field, Location location, boolean randomAge, Gender sex)
 46	    {
 47	        super(randomProvider, field, location);
 48	        this.sex = sex;
 49	        Random rand = getRandomProvider().getRandom();
 50	        if(randomAge) {
 51	            this.age = rand.nextInt(getMaxAge());
 52	            foodLevel = rand.nextInt(getMaxFoodLevel());
 53	        }
 54	        else {
 55	            this.age = 0;
 56	            foodLevel = getMaxFoodLevel();
 57	        }
 58	    }
 59	
 60	    /**
 61	     * Make this animal act - that is: make it do
 62	     * whatever it wants/needs to do.
 63	     * @param newAnimals A list to receive newly born animals.
 64	     * @param environment The environment that the animal resides in.
 65	     */
 66	    public void act(List<Actor> newAnimals, Environment environment)
 67	    {
 68	        Random rand = getRandomProvider().getRandom();
 69	        incrementAge();
 70	        incrementHunger();
 71	        if(isAlive()) {
 72	            giveBirth(newAnimals, environment);
 73	            // Move towards a source of food if found.
 74	            Location newLocation = findFood(environment);
 75	            if(newLocation == null) {
 76	                // No food found - try to move to a free location.
 77	                newLocation = getField().freeAdjacentLocation(getLocation());
 78	            }
 79	
 80	            // list of adjacent locations that contain an instance of Grass
 81	            List<Location> adjacentGrassSpots = getField().adjacentLocationsWithSpecies(getLocation(), Grass.class);
 82	
 83	            if(newLocation != null) {
 84	                // See if it was possible to move.
 85	                setLocation(newLocation);
 86	            }
 87	            else if (adjacentGrassSpots.size() > 0) {
 88	                // if there is grass adjacent to the animal, clear the current location
 89	                // and move to a random location that contained grass
 90	                getField().clear(getLocation());
 91	                setLocation(adjacentGrassSpots.get(rand.nextInt(adjacentGrassSpots.size())));
 92	            }
 93	            else {
 94	                // Overcrowding
 95	                setDead();
 96	            }
 97	        }
 98	    }
 99	
100	    /**
101	     * Look for food adjacent to the current location.
102	     * Only the first food is eaten.
103	     * @return Where food was found, or null if it wasn't.
104	     */
105	    protected Location findFood(Environment environment)
106	    {
107	        return findFood();
108	    }
109	
110	    /**
111	     * Look for food adjacent to the current location.
112	     * Only the first food is eaten.
113	     * @return Where food was found, or null if it wasn't.
114	     */
115	    protected Location findFood()
116	    {
117	        Field field = getField();
118	        DiseaseService diseaseService = field.getDiseaseService();
119	        List<Location> adjacent = field.adjacentLocations(getLocation());
120	        diseaseService.applyAdjacentExposure(this, adjacent, field);
121	        Iterator<Location> it = adjacent.iterator();
122	        // only eats if it's not full (food level less than max)
123	        while(it.hasNext() && foodLevel <= getMaxFoodLevel()) {
124	            Location where = it.next();
125	            Object animal = field.getObjectAt(where);
126	            if(animal != null && getDiet().contains(animal.getClass()))
127	            {
128	                Organism food = (Organism) animal;
129	                diseaseService.applyFoodborneExposure(this, food);
130	                if(food.isAlive()) 
131	                {
132	                    food.setDead();
133	                    int newFoodLevel = foodLevel + food.getFoodValue();
134	
135	                    // caps the food level at the maximum
136	                    foodLevel = Math.min(newFoodLevel, getMaxFoodLevel());
137	
138	                    return where;
139	                }
140	                return where;
141	            }
142	        }
143	        return null;
144	    }
145	
146	    /**
147	     * Check whether this animal is to give birth at this step.
148	     * New births will be made into free adjacent locations.
149	     * @param newAnimals A list to return newly born animals.
150	     * @param environment The environment that the animal resides in. 
151	     */
152	    protected void giveBirth(List<Actor> newAnimals, Environment environment)
153	    {
154	        Field field = getField();
155	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
156	        int births = breed();
157	        for(int b = 0; b < births && !free.isEmpty(); b++) {
158	            Location loc = free.remove(0);
159	            Gender sex = getRandomProvider().getRandom().nextBoolean() ? Gender.MALE : Gender.FEMALE;
160	            newAnimals.add(createYoung(field, loc, sex));
161	        }
162	    }
163	
164	    protected Animal createYoung(Field field, Location location, Gender sex)
165	    {
166	        return field.getOrganismFactory().createOffspring(getClass().asSubclass(Animal.class), field, location, sex);
167	    }
168	
169	    /**
170	     * Returns true if the animal is awake or not.
171	     */
172	    public boolean isAwake(Environment environment)
173	    {
174	        if(isNocturnal){
175	            return !environment.getTime().isDay();
176	        }
177	        return environment.getTime().isDay();
178	    }
179	
180	    /**
181	     * Generates a number representing the number of births,
182	     * if it can breed.
183	     * @return The number of births (may be zero)
184	     */
185	    protected int breed()
186	    {
187	        Random rand = getRandomProvider().getRandom();
188	        int births = 0;
189	        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
190	            births = rand.nextInt(getMaxLitterSize()) + 1;
191	            Animal mate = (Animal) getPotentialMates().get(rand.nextInt(getPotentialMates().size()));
192	            getField().getDiseaseService().applySexualExposure(this, mate);
193	        }
194	        return births;
195	    }
196	
197	    /**
198	     * Returns true if the animal is able to breed.
199	     * Returns false if otherwise. 
200	     */
201	    protected boolean canBreed()
202	    {
203	        return age >= getBreedingAge() && !getPotentialMates().isEmpty();
204	    }
205	
206	    /**
207	     * Returns a list of potential mates. Mates have to be
208	     * of a opposite gender. 
209	     * @return List<Organism> A list of potential mates.
210	     */
211	    protected List<Organism> getPotentialMates()
212	    {
213	        List<Organism> potentialMates = new ArrayList<>();
214	        if(getField() != null){
215	            potentialMates = getField().adjacentLocations(getLocation()).stream()
216	                    .map(s -> getField().getObjectAt(s))
217	                    .filter(s -> s != null)
218	                    .filter(s -> s.getClass().equals(this.getClass()))
219	                    .filter(s -> this.sex != ((Animal) s).sex)
220	                    .map(s -> (Organism) s)
221	                    .collect(Collectors.toList());
222	            // stream counts the number of Animals of the same species, as well as opposite gender
223	        }
224	        return potentialMates;
225	    }
226	
227	
228	    /**
229	     * Increase the age. This could result in the animal's death.
230	     */
231	    protected void incrementAge()
232	    {
233	        this.age++;
234	        if(this.age > getMaxAge()) {
235	            setDead();
236	        }
237	    }
238	
239	    /**
240	     * Make this animal more hungry. This could result in the animal's death.
241	     */
242	    protected void incrementHunger()
243	    {
244	        foodLevel--;
245	        if(foodLevel <= 0) {
246	            setDead();
247	        }
248	    }
249	
250	}

