 26	    public OrganismFactory(RandomProvider randomProvider, SimulationConfig config, DiseaseService diseaseService)
 27	    {
 28	        this.randomProvider = randomProvider;
 29	        this.config = config;
 30	        this.diseaseService = diseaseService;
 31	        this.creators = Map.ofEntries(
 32	                Map.entry(Grass.class, (field, location, options) -> new Grass(field, location)),
 33	                Map.entry(Hunter.class, (field, location, options) -> new Hunter(field, location)),
 34	                Map.entry(Deer.class, (field, location, options) -> new Deer(options.randomAge(), field, location, requireSex(options))),
 35	                Map.entry(Coyote.class, (field, location, options) -> new Coyote(options.randomAge(), field, location, requireSex(options))),
 36	                Map.entry(Wolf.class, (field, location, options) -> new Wolf(options.randomAge(), field, location, requireSex(options))),
 37	                Map.entry(Eagle.class, (field, location, options) -> new Eagle(options.randomAge(), field, location, requireSex(options))),
 38	                Map.entry(Mouse.class, (field, location, options) -> new Mouse(options.randomAge(), field, location, requireSex(options)))
 39	        );
 40	    }
