 42	    public List<Actor> populate(Field field)
 43	    {
 44	        List<Actor> actors = new ArrayList<>();
 45	        int hunterCount = 0;
 46	
 47	        field.clear();
 48	        for(int row = 0; row < field.getDepth(); row++) {
 49	            for(int col = 0; col < field.getWidth(); col++) {
 50	                Location location = new Location(row, col);
 51	                Organism organism = maybeCreateOrganism(field, location, hunterCount);
 52	                if(organism != null) {
 53	                    actors.add((Actor) organism);
 54	                    if(organism instanceof Hunter) {
 55	                        hunterCount++;
 56	                    }
 57	                }
 58	            }
 59	        }
 60	
 61	        return actors;
 62	    }
