 64	    public List<Actor> createGrassPatches(Field field, Environment environment)
 65	    {
 66	        Random rand = randomProvider.getRandom();
 67	        if(environment.getWeather().getCurrentWeather() != WeatherType.RAINING) {
 68	            return List.of();
 69	        }
 70	
 71	        double creationRate = config.getCreationProbability(Grass.class);
 72	        List<Actor> grassActors = new ArrayList<>();
 73	        for(Location location : field.getRandomFreePatches(creationRate)) {
 74	            if(rand.nextDouble() <= creationRate) {
 75	                grassActors.add(createOffspring(Grass.class, field, location));
 76	            }
 77	        }
 78	
 79	        return grassActors;
 80	    }
