 93	    public <T extends Organism> T createOffspring(Class<T> organismClass,
 94	            Field field,
 95	            Location location,
 96	            Animal.Gender sex)
 97	    {
 98	        return create(organismClass, field, location, new OrganismCreationOptions(false, sex));
 99	    }
