101	    private Organism maybeCreateOrganism(Field field, Location location, int hunterCount)
102	    {
103	        Random rand = randomProvider.getRandom();
104	        for(Class<? extends Organism> organismClass : CREATION_ORDER) {
105	            if(organismClass == Hunter.class && hunterCount >= config.getHunterLimit()) {
106	                continue;
107	            }
108	
109	            if(rand.nextDouble() <= config.getCreationProbability(organismClass)) {
110	                return createInitialOrganism(organismClass, field, location);
111	            }
112	        }
113	
114	        return null;
115	    }
