117	    private <T extends Organism> T create(Class<T> organismClass,
118	            Field field,
119	            Location location,
120	            OrganismCreationOptions options)
121	    {
122	        OrganismCreator<? extends Organism> creator = creators.get(organismClass);
123	        if(creator == null) {
124	            throw new IllegalArgumentException("Unsupported organism type: " + organismClass.getName());
125	        }
126	
127	        T organism = organismClass.cast(creator.create(field, location, options));
128	        diseaseService.initializeOrganism(organism);
129	        return organism;
130	    }
